{
  "description": "The creature is shown in right-facing side profile standing on four legs against a plain off-white background. It has the overall shape, fur, head and paws of a large brown bear, but most of its body is covered by a glossy, dark reddish-brown segmented exoskeleton. A large domed carapace of overlapping transverse bands covers the back from behind the neck to the base of the tail, with additional large smooth plates over the shoulders and hips and smaller overlapping plates down the outer sides of all four limbs. The chest, belly, throat and inner surfaces of the limbs show lighter beige, ribbed and pitted segmented plating between the dark plates and the brown fur. The head, lower legs and paws remain furry, and a short segmented tail extends from the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with dense shaggy brown fur, a lighter tan muzzle, a large black nose, small dark brown eyes and a closed mouth",
      "where": "at the front of the body, connected to the armored neck"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur with slightly lighter edges",
      "where": "on top of the head, one on each side"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs covered in brown fur with glossy dark reddish-brown armor plates on the outer front and outer hind surfaces and lighter beige ribbed segmented plating on the inner and underside surfaces",
      "where": "underneath the body, two forelegs beneath the chest and two hind legs beneath the rear"
    },
    {
      "part": "feet",
      "looks_like": "four large bear-like paws with brown fur on top and five long curved dark claws on each foot",
      "where": "at the bottom of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short narrow segmented tail with glossy dark reddish-brown plates on top and a lighter beige underside with small pointed projections along the edge, tapering to a point",
      "where": "extending from the rear of the body behind the dorsal carapace"
    },
    {
      "part": "shell",
      "looks_like": "large glossy dark reddish-brown dorsal carapace made of about 8-9 overlapping transverse bands with thin tan lines between them, smooth and reflective with some surface scratches",
      "where": "covering the entire back from just behind the neck to the base of the tail"
    },
    {
      "part": "plates",
      "looks_like": "numerous glossy dark reddish-brown armor plates of varying size - large smooth domed plates over the shoulders and hips, smaller overlapping plates on the throat, sides of neck, and down the front and back of all four limbs, and lighter beige plates with rows of oval pits and fine ribbing on the chest, belly and inner legs",
      "where": "over the shoulders, chest, sides of neck, belly, and encircling the upper and lower portions of all four legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "isopod"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
